def digits_count(n):
    if n == 0:
        return 1
    count = 0
    while n > 0:
        n = n // 10
        count = count + 1
    return count

def collatz_steps(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = n * 3 + 1
        steps = steps + 1
    return steps

def binary_guess(secret):
    lo = 1
    hi = 100
    tries = 0
    while True:
        mid = (lo + hi) // 2
        tries = tries + 1
        if mid == secret:
            return tries
        if mid < secret:
            lo = mid + 1
        else:
            hi = mid - 1
